INSERT INTO ifws_git_capability (code, label, definition) VALUES ('CloneUrl', 'clone URL', 'The URL a repository is cloned from, for a path of the workspace and the reverse.');
INSERT INTO ifws_git_capability (code, label, definition) VALUES ('Credentials', 'credentials', 'Authentication through a Git credential helper, the host''s command-line tool or a token from the environment, never a secret stored in a file.');
INSERT INTO ifws_git_capability (code, label, definition) VALUES ('DefaultBranch', 'default branch', 'The name of the branch the remote presents as its default.');
INSERT INTO ifws_git_capability (code, label, definition) VALUES ('SignedCommits', 'signed commits', 'Whether a commit''s signature, OpenPGP or SSH, can be seen as verified.');
INSERT INTO ifws_git_capability (code, label, definition) VALUES ('ProtectedBranches', 'protected branches', 'Whether a branch can be asked about as protected: no push, no force, review required.');
INSERT INTO ifws_git_capability (code, label, definition) VALUES ('Issues', 'issues', 'Issues of the repository, behind the interface.');
INSERT INTO ifws_git_capability (code, label, definition) VALUES ('ChangeRequests', 'change requests', 'A pull request (GitHub) or a merge request (GitLab), behind the interface.');
INSERT INTO ifws_git_capability (code, label, definition) VALUES ('NestedGroups', 'nested groups', 'Groups to any depth between the host and the repository (GitLab); a host without them has one owner level.');
INSERT INTO ifws_action_kind (code, label, definition) VALUES ('Clone', 'clone', 'Clone a repository that is missing.');
INSERT INTO ifws_action_kind (code, label, definition) VALUES ('FastForward', 'fast-forward', 'Move a branch that is behind its remote forward, with no merge, rebase or reset.');
INSERT INTO ifws_action_kind (code, label, definition) VALUES ('CreateWorktree', 'create worktree', 'Add a worktree of a repository for a branch.');
INSERT INTO ifws_action_kind (code, label, definition) VALUES ('ConfigureRepo', 'configure repository', 'Set a repository''s local Git configuration: its hooks path, signing and, on Windows, long paths.');
INSERT INTO ifws_action_kind (code, label, definition) VALUES ('ConfigureHost', 'configure host', 'Change the host outside the workspace: the Windows long-path setting, the global Git include or the shell snippet; only `ifws setup` may do it.');
INSERT INTO ifws_action_kind (code, label, definition) VALUES ('WriteGenerated', 'write generated file', 'Write a generated file inside the workspace.');
INSERT INTO ifws_action_kind (code, label, definition) VALUES ('RemoveGenerated', 'remove generated file', 'Remove a generated file that the state record holds and nobody edited.');
INSERT INTO ifws_action_kind (code, label, definition) VALUES ('InstallTool', 'install tool', 'Install a pinned artifact of the tool catalog into the workspace''s tool store; only `ifws setup` may do it.');
INSERT INTO ifws_action_kind (code, label, definition) VALUES ('Skip', 'skip', 'Do nothing, and say why.');
INSERT INTO ifws_action_kind (code, label, definition) VALUES ('Refuse', 'refuse', 'Do nothing because doing it would not be safe, and say why.');
INSERT INTO ifws_severity (code, label, definition) VALUES ('Informational', 'informational', 'To be known, never failing a run.');
INSERT INTO ifws_severity (code, label, definition) VALUES ('Warning', 'warning', 'To be fixed; a run that has one exits with findings.');
INSERT INTO ifws_severity (code, label, definition) VALUES ('Error', 'error', 'Wrong now; a run that has one exits with findings and a plan does not act on what it names.');
INSERT INTO ifws_repo_state (code, label, definition) VALUES ('Missing', 'missing', 'Nothing is at the repository''s path.');
INSERT INTO ifws_repo_state (code, label, definition) VALUES ('Clean', 'clean', 'The branch equals its remote and the working tree has no change.');
INSERT INTO ifws_repo_state (code, label, definition) VALUES ('Dirty', 'dirty', 'The working tree has uncommitted or untracked changes.');
INSERT INTO ifws_repo_state (code, label, definition) VALUES ('Ahead', 'ahead', 'The branch has commits its remote does not.');
INSERT INTO ifws_repo_state (code, label, definition) VALUES ('Behind', 'behind', 'The remote has commits the branch does not, and the branch has none of its own.');
INSERT INTO ifws_repo_state (code, label, definition) VALUES ('Diverged', 'diverged', 'Both the branch and its remote have commits the other lacks.');
INSERT INTO ifws_repo_state (code, label, definition) VALUES ('Locked', 'locked', 'A Git lock file is present: another process may be working in the repository.');
INSERT INTO ifws_repo_state (code, label, definition) VALUES ('Detached', 'detached', 'HEAD is on no branch.');
INSERT INTO ifws_repo_state (code, label, definition) VALUES ('WrongRemote', 'wrong remote', 'The repository at the path has a remote other than the one the manifest names.');
INSERT INTO ifws_repo_state (code, label, definition) VALUES ('NotARepo', 'not a repository', 'Something other than a Git repository is at the path.');
INSERT INTO ifws_git_manager_kind (code, label, definition) VALUES ('Github', 'GitHub', 'GitHub, public and private repositories: an owner and a repository.');
INSERT INTO ifws_git_manager_kind (code, label, definition) VALUES ('Gitlab', 'GitLab', 'GitLab, public and private repositories, in groups to any depth.');
INSERT INTO ifws_git_manager_kind (code, label, definition) VALUES ('Git', 'plain Git', 'Any other Git remote: what Git itself offers and nothing a host adds.');
INSERT INTO ifws_module_source (code, label, definition) VALUES ('BuiltIn', 'built-in', 'A typed module the command holds.');
INSERT INTO ifws_module_source (code, label, definition) VALUES ('Registered', 'registered', 'A module the workspace names in `modules.auto.json`.');
INSERT INTO ifws_module_source (code, label, definition) VALUES ('Path', 'on the path', 'An executable named `ifws-*` on the `PATH`, like Git''s `git-foo`.');
INSERT INTO ifws_exit_status (code, label, definition) VALUES ('Ok', 'ok', 'The run did what was asked and has no warning or error.');
INSERT INTO ifws_exit_status (code, label, definition) VALUES ('Findings', 'findings', 'The run ended and has at least one warning or error.');
INSERT INTO ifws_exit_status (code, label, definition) VALUES ('Usage', 'usage', 'The command line is wrong: an unknown command, option or argument.');
INSERT INTO ifws_exit_status (code, label, definition) VALUES ('Environment', 'environment', 'The host cannot run it: a missing tool, an unwritable or absent home, an unsupported runtime.');
